// Generated by Cypress Author on 2026-10-13

// E2E coverage for the MDX Editor Goldmark demo at /components/mdxEditor.
// It verifies authenticated access, explicit server rendering through the
// authenticated /api/renderMd proxy, editor-mode continuity, real Vim command
// behavior, synchronized output tabs, failure resilience, responsive layout,
// keyboard accessibility, and server-side sanitization through one live path.

import { visualEditable } from "../support/mdxEditor.js";

const DEMO_PATH = "/components/mdxEditor";

function openDemo() {
  cy.signInAsUser(0);
  cy.visit(DEMO_PATH);
  cy.waitForClerkLoaded();
  cy.get("[data-cy='mdx-editor-demo']", { timeout: 20000 }).should("exist");
}

describe("mdxEditor demo", () => {
  describe("authentication route", () => {
    it("signed-out visit → redirected away from the demo", () => {
      cy.visit(DEMO_PATH, { failOnStatusCode: false });
      cy.location("pathname", { timeout: 20000 }).should(
        "not.eq",
        DEMO_PATH,
      );
      cy.get("[data-cy='mdx-editor-demo']").should("not.exist");
    });

    it("signed-in visit → demo renders within the component page", () => {
      openDemo();
      cy.get("[data-cy='mdx-render']").should("exist");
      cy.get("[data-cy='mdx-vim-toggle']").should("exist");
    });
  });

  describe("initial state and explicit rendering", () => {
    beforeEach(openDemo);

    it("initial load → visual editor shows the sample draft and empty output", () => {
      cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
        "exist",
      );
      cy.get("[data-cy='mdx-vim-toggle']").should(
        "have.attr",
        "aria-pressed",
        "false",
      );
      cy.contains("Render Markdown to create output").should("exist");
    });

    it("editing and switching tabs issue no request; Render issues exactly one exact POST", () => {
      cy.intercept("POST", "/api/renderMd").as("render");

      // Tab changes do not submit.
      cy.get("[data-cy='mdx-tab-html']").click();
      cy.get("[data-cy='mdx-tab-markdown']").click();

      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@render").then((interception) => {
        expect(interception.request.method).to.eq("POST");
        expect(interception.request.headers["content-type"]).to.contain(
          "application/json",
        );
        expect(interception.request.body).to.have.property("text");
        expect(interception.request.body.text).to.be.a("string");
      });
      // Only one request was made.
      cy.get("@render.all").should("have.length", 1);
    });

    it("Render → synchronized Markdown, HTML source, and preview tabs", () => {
      cy.intercept("POST", "/api/renderMd").as("render");
      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@render");

      cy.get("[data-cy='mdx-tab-markdown']").click();
      cy.get("[data-cy='mdx-output-markdown']").should("contain.text", "#");

      cy.get("[data-cy='mdx-tab-html']").click();
      cy.get("[data-cy='mdx-output-html']").should("contain.text", "<h1");

      cy.get("[data-cy='mdx-tab-preview']").click();
      cy.get("[data-cy='mdx-preview'] h1").should("exist");
    });
  });

  describe("editor continuity and Vim behavior", () => {
    beforeEach(openDemo);

    it("switch visual → Vim preserves the draft, and a real `dd` edits it", () => {
      // Ensure the visual editor has fully mounted before toggling, so the
      // toggle's onChange is not raced by the lazy chunk still loading.
      cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
        "exist",
      );
      cy.get("[data-cy='mdx-vim-toggle']").click();
      cy.get("[data-cy='mdx-vim-toggle']").should(
        "have.attr",
        "aria-pressed",
        "true",
      );
      cy.get("[data-cy='mdx-vim-editor']", { timeout: 20000 }).should("exist");

      // First line of the sample is the "# MDXEditor Goldmark demo" heading.
      cy.get("[data-cy='mdx-vim-editor'] .cm-content").should(
        "contain.text",
        "MDXEditor Goldmark demo",
      );

      // Enter normal mode, go to the top, delete the first line.
      cy.get("[data-cy='mdx-vim-editor'] .cm-content").click({ force: true });
      cy.focused().type("{esc}");
      cy.focused().type("ggdd");

      cy.get("[data-cy='mdx-vim-editor'] .cm-content").should(
        "not.contain.text",
        "# MDXEditor Goldmark demo",
      );

      // Switch back to visual; the edit persists in the shared draft.
      cy.get("[data-cy='mdx-vim-toggle']").click();
      cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
        "exist",
      );
      cy.get("[data-cy='mdx-visual-editor']").should(
        "not.contain.text",
        "# MDXEditor Goldmark demo",
      );
    });
  });

  describe("resilience", () => {
    beforeEach(openDemo);

    it("establish success, then a 500 → prior output and an alert remain", () => {
      cy.intercept("POST", "/api/renderMd").as("render");
      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@render");
      cy.get("[data-cy='mdx-tab-preview']").click();
      cy.get("[data-cy='mdx-preview'] h1").should("exist");

      // Next request fails; the previous snapshot must remain.
      cy.intercept("POST", "/api/renderMd", {
        statusCode: 500,
        body: { message: "boom" },
      }).as("renderFail");
      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@renderFail");

      cy.get("[data-cy='mdx-error']").should("not.be.empty");
      cy.get("[data-cy='mdx-preview'] h1").should("exist");
    });
  });

  describe("live sanitizer path", () => {
    beforeEach(openDemo);

    it("submit safe + unsafe Markdown through the real proxy → safe kept, unsafe stripped", () => {
      cy.intercept("POST", "/api/renderMd").as("render");

      // Replace the draft via the Vim source editor (plain contenteditable).
      cy.get("[data-cy='mdx-vim-toggle']").click();
      cy.get("[data-cy='mdx-vim-toggle']").should(
        "have.attr",
        "aria-pressed",
        "true",
      );
      cy.get("[data-cy='mdx-vim-editor'] .cm-content", {
        timeout: 20000,
      }).should("exist");
      // CodeMirror's content node is wrapped by its own scroller; force the
      // click past the ancestor actionability check onto the real editable.
      cy.get("[data-cy='mdx-vim-editor'] .cm-content").click({ force: true });
      cy.focused().type("{esc}");
      cy.focused().type("ggVGd", { delay: 0 }); // clear whole document
      cy.focused().type("i", { delay: 0 });
      cy.focused().type(
        "[ok](https://example.com)\n\n<script>alert(1)</script>",
        { delay: 0, parseSpecialCharSequences: false },
      );
      cy.focused().type("{esc}");

      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@render").its("response.statusCode").should("eq", 200);

      cy.get("[data-cy='mdx-tab-html']").click();
      cy.get("[data-cy='mdx-output-html']").should(
        "contain.text",
        'href="https://example.com"',
      );
      cy.get("[data-cy='mdx-output-html']").should(
        "not.contain.text",
        "<script",
      );

      cy.get("[data-cy='mdx-tab-preview']").click();
      cy.get("[data-cy='mdx-preview'] script").should("not.exist");
      cy.get("[data-cy='mdx-preview'] a").should(
        "have.attr",
        "href",
        "https://example.com",
      );
    });
  });

  describe("responsive layout", () => {
    beforeEach(openDemo);

    it("wide viewport → authoring and output rows have comparable heights", () => {
      cy.viewport(1280, 900);
      cy.get("[data-cy='mdx-editor-demo'] section[aria-labelledby='mdx-authoring-heading']")
        .invoke("outerHeight")
        .then((authoring) => {
          cy.get(
            "[data-cy='mdx-editor-demo'] section[aria-labelledby='mdx-output-heading']",
          )
            .invoke("outerHeight")
            .then((output) => {
              expect(Math.abs(Number(authoring) - Number(output))).to.be.lessThan(
                24,
              );
            });
        });
    });

    it("narrow viewport → no horizontal page overflow", () => {
      cy.viewport("iphone-6");
      cy.document().then((doc) => {
        expect(doc.documentElement.scrollWidth).to.be.lessThan(
          doc.documentElement.clientWidth + 2,
        );
      });
    });
  });

  describe("keyboard accessibility", () => {
    beforeEach(openDemo);

    it("Render activates from the keyboard and exposes live regions", () => {
      cy.intercept("POST", "/api/renderMd").as("render");
      cy.get("[data-cy='mdx-render']").focus().type("{enter}");
      cy.wait("@render");
      cy.get("[data-cy='mdx-status']")
        .should("have.attr", "role", "status")
        .and("have.attr", "aria-live", "polite");
      cy.get("[data-cy='mdx-error']").should("have.attr", "role", "alert");
    });

    it("output tabs expose tablist semantics and arrow navigation", () => {
      cy.intercept("POST", "/api/renderMd").as("render");
      cy.get("[data-cy='mdx-render']").click();
      cy.wait("@render");
      cy.get("[data-cy='mdx-tab-markdown']").click();
      cy.get("[data-cy='mdx-tab-markdown']").type("{rightArrow}");
      cy.get("[data-cy='mdx-tab-html']").should(
        "have.attr",
        "aria-selected",
        "true",
      );
    });
  });

  // Added for the reusable-editor extraction.
  describe("reusable editor extraction", () => {
    beforeEach(openDemo);

    it("mounts the editor inside the reusable fixed-sizing shell", () => {
      cy.get("[data-cy='mdx-editor']", { timeout: 20000 })
        .should("exist")
        .and("have.attr", "data-sizing", "fixed");
    });

    it("Ctrl+Enter inside the editor renders without clicking the button", () => {
      cy.intercept("POST", "/api/renderMd").as("render");
      cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
        "exist",
      );
      // The contenteditable is taller than the fixed-height shell, so its
      // centre is clipped and covered by a sibling; click a visible position.
      visualEditable().click("top").type("{ctrl+enter}");
      cy.wait("@render");
      cy.get("@render.all").should("have.length", 1);
    });

    it("loads the Vim editor chunk only after Vim mode is requested", () => {
      // The Vim adapter is a separate lazy chunk; its module request must not
      // happen until the toggle is activated.
      cy.intercept("GET", "**/VimMarkdownEditor*.js").as("vimChunk");
      cy.get("[data-cy='mdx-visual-editor']", { timeout: 20000 }).should(
        "exist",
      );
      cy.get("[data-cy='mdx-vim-editor']").should("not.exist");

      cy.get("[data-cy='mdx-vim-toggle']").click();
      cy.get("[data-cy='mdx-vim-editor']", { timeout: 20000 }).should("exist");
    });
  });
});
